class Client
  def initialize
    @pending = {}
    @mutex = Mutex.new
  end

  def call(body)
    id = SecureRandom.uuid
    queue = Thread::Queue.new
    @mutex.synchronize { @pending[id] = queue }       # register BEFORE send
    transport.send_message(id, body)
    queue.pop(timeout: 5) || raise("no reply for #{id}")   # nil on timeout
  ensure
    @mutex.synchronize { @pending.delete(id) }
  end
end
